 *  approved without a proof; proof-threshold-<grade>: the grade's own proof threshold, used for a claim of a
 *  person of that grade instead of the sheet's while one is in force on its date; note-threshold: one above it cannot be opened with an empty note; review-threshold: one above it goes to REVIEW when opened; rounding: the rounding mode, half-up or half-even, a claim of a date with one in force rounds its live figures by it; grace-<grade>: the grade's grace days, see `overdueFrom`), oldest from-date first. `permissions` is the permission matrix entries set, by action
 *  (open, settle, void, reassign, close, reopen): the roles that may take it, comma separated; an action not listed
 *  keeps the standing rule (open, settle, void and close by clerk and steward; reassign and reopen by steward).
 *  `graceDays` is the days after a period's to-date it is left open (null when blank: off; not dated): changing the
 *  sheet's today closes each open period lapsed past them. `delegations` is each delegation of the steward role
 *  made on the sheet, oldest first. `entryDate` is the entry date (yyyy-mm-dd; null when blank: off; not dated): while
 *  set, it is the default date of a new claim instead of the sheet's today. `holidays` is the sheet's holidays
 *  (yyyy-mm-dd), earliest first: a claim's due-by, fixed when it is created, that falls on one is moved to the next
 *  day that is not one. `voidReasons` is the sheet's void reasons, in the order they were added: while there is one,
 *  voiding a claim needs one of them. `pot` is the sheet's pot (two decimals; null when blank: none; not dated): each
 *  member of a balanced pool gets a cut of it. `parent` is the sheet's parent sheet id (null when blank: none; not
 *  dated): a grade with no rate in force on a date takes the parent's, then its parent's, up to three levels up.
 *  `fiscalStartMonth` is the month (1 to 12; 1 unless set; not dated) the sheet's fiscal year starts in.
 *  `alertThreshold` is the sheet's alert threshold (two decimals; null when blank: off; not dated): a person whose
 *  due-total goes from at or below it to above it is written an ALERT line. */
export type Settings = { clerkLimit: string | null; floor: string; terms: number; latePct: string; roles: Role[]; policyDate: string | null; periodNumberingFrom: string | null;
  gradeTerms: Record<string, number>; cap: string | null; dated: Record<string, DatedValue[]>;
  permissions: Record<string, string>; graceDays: number | null; delegations: Delegation[];
  entryDate: string | null; holidays: string[]; voidReasons: string[]; pot: string | null;
  parent: string | null; fiscalStartMonth: number; alertThreshold: string | null };

/** A steward's (`by`) delegation of the steward role to a user, from a date to a date (yyyy-mm-dd, inclusive):
 *  <period>-<n>, or X-<n> in no period; blank is off), each grade's own terms (blank is the sheet's
 *  terms), its cap (the most a person's due-total can be; blank is none), its proof threshold (a claim whose due is
 *  above the one in force on its date cannot be settled or approved without a proof; blank is none), its note threshold (a claim
 *  whose due is above the one in force on its date cannot be opened with an empty note; blank is none), its rounding mode
 *  (half-up or half-even: a claim whose date has one in force rounds its live figures by it instead of by the policy date;
 *  blank is none), its permission matrix (for each of open, settle, void,
 *  reassign, close and reopen, the roles that may do it, comma separated; blank keeps the standing rule; not dated), its grace days (changing the
 *  sheet's today closes each open period whose to-date plus them is before the new today; blank is off; not dated), its entry date (while set, the default date of a new claim — the claim form, the
 *  quick-add bar, a pasted line with a blank date and a correction — instead of the sheet's today; blank is off; not dated), its pot (two
 *  decimals, shared out as the cuts of each balanced pool; blank is none; not dated), its parent sheet (a grade with no
 *  rate in force on a date takes the parent's, then the parent's parent's, up to three levels up; a sheet that has been
  const [voidReason, setVoidReason] = useState('');

  const saveOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { clerkLimit: string | null; floor: string | null; terms: string | null; latePct: string | null; policyDate: string | null; periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null; from: Record<string, string>; proofThreshold: string | null; noteThreshold: string | null; permissions: Record<string, string>; graceDays: string | null; entryDate: string | null; gradeGrace: Record<string, string>; gradeProofThreshold: Record<string, string>; pot: string | null; parent: string | null; fiscalStartMonth: string | null; alertThreshold: string | null; rounding: string | null; reviewThreshold: string | null }) =>
      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, f),
    onSuccess: (saved) => {
      setLimit(null);
      setFloor(null);
      setTerms(null);
      setGradeTerms({});
      setGradeGrace({});
      setGradeProof({});
      setLatePct(null);
      setPolicyDate(null);
      setNumberingFrom(null);
      setCap(null);
      setProofThreshold(null);
      setNoteThreshold(null);
      setReviewThreshold(null);
      setFrom({});
      setPermissions({});
      setGraceDays(null);
      setEntryDate(null);
      setPot(null);
      setParent(null);

  return (
    <section data-testid="settings">
      <p>
        Parent sheet: <strong data-testid="sheet-parent">{settings.data?.parent ?? ''}</strong>
      </p>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          saveOnce(() => {
            save.reset();
            return save.mutateAsync({ clerkLimit: limit, floor, terms, latePct, policyDate, periodNumberingFrom: numberingFrom, gradeTerms, cap, from, proofThreshold, noteThreshold, permissions, graceDays, entryDate, gradeGrace, gradeProofThreshold: gradeProof, pot, parent, fiscalStartMonth, alertThreshold, rounding, reviewThreshold });
          });
        }}
      >

